function selectRoom(){filtered=data.filter(x=>x.room===Number(el('room').value));el('asset').replaceChildren(...filtered.map((x,i)=>option(i,x.kind==='background'?'Bakgrund':`${x.id} · ${x.name||'(utan namn)'}`)));selectAsset()}
function selectAsset(){current=filtered[Number(el('asset').value)];el('version').replaceChildren(...current.versions.map((p,i)=>option(i,p.split('/').at(-1))));el('version').value=String(current.versions.length-1);el('original').src=current.original;el('overlayOriginal').src=current.original;el('details').textContent=`Rum ${current.room} · ${current.kind==='object'?'Objekt '+current.id+' · ':''}${current.width} × ${current.height} originalpixlar${current.x!==undefined?' · position '+current.x+', '+current.y:''} · ${current.versions.length} sparade versioner`;selectVersion()}
function selectVersion(){const p=current.versions[Number(el('version').value)];for(const id of ['generated','overlayGenerated']){if(p){el(id).src=p;el(id).hidden=false}else{el(id).removeAttribute('src');el(id).hidden=true}}}
el('room').onchange=selectRoom;el('asset').onchange=selectAsset;el('version').onchange=selectVersion;el('prev').onclick=()=>step(-1);el('next').onclick=()=>step(1);function step(d){el('asset').value=String((Number(el('asset').value)+d+filtered.length)%filtered.length);selectAsset()}
